import{_ as a,o as r,c as t,a5 as n}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"PE 加载过程：从文件到进程","description":"前面的章节讲的是「文件」。这一章把 PE 格式串起来，看 Windows 加载器（Loader）如何把一个躺在硬盘上的 .exe，变成内存里正在运行的进程。理解加载过程，才能解释很多运行时现象，比如「为什么文件里的布局和内存里的布局不一样」「导入函数地址是什么时候确定的」。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/04-pe-format/chapter-04-pe-loading.md","filePath":"reverse-engineering/04-pe-format/chapter-04-pe-loading.md"}'),i={name:"reverse-engineering/04-pe-format/chapter-04-pe-loading.md"};function d(l,e,s,p,o,c){return r(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="pe-加载过程-从文件到进程" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">PE 加载过程：从文件到进程 <a class="header-anchor" href="#pe-加载过程-从文件到进程" aria-label="Permalink to &quot;PE 加载过程：从文件到进程&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">前面的章节讲的是「文件」。这一章把 PE 格式串起来，看 Windows 加载器（Loader）如何把一个躺在硬盘上的 <code>.exe</code>，变成内存里正在运行的进程。理解加载过程，才能解释很多运行时现象，比如「为什么文件里的布局和内存里的布局不一样」「导入函数地址是什么时候确定的」。</p><h2 id="_1-加载的整体流程" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">1. 加载的整体流程 <a class="header-anchor" href="#_1-加载的整体流程" aria-label="Permalink to &quot;1. 加载的整体流程&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">加载器启动一个 PE 文件，大致经历以下步骤：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取 PE 头 → 分配内存并映射节区 → 加载依赖 DLL</span></span>
<span class="line"><span>→ 解析导入表（填充 IAT）→ 处理重定位 → 执行 TLS 回调</span></span>
<span class="line"><span>→ 跳转到入口点（AddressOfEntryPoint）→ 程序开始运行</span></span></code></pre></div><p data-src-line="16" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">下面逐个环节说明。</p><h2 id="_2-映射节区-文件布局-内存布局" tabindex="-1" data-src-line="18" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">2. 映射节区：文件布局 ≠ 内存布局 <a class="header-anchor" href="#_2-映射节区-文件布局-内存布局" aria-label="Permalink to &quot;2. 映射节区：文件布局 ≠ 内存布局&quot;">​</a></h2><p data-src-line="20" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">加载器先读 PE 头，按 <code>SizeOfImage</code> 在内存里预留一块区域，然后把各个节区「映射」进内存。</p><p data-src-line="22" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">关键在于：<strong>节区在文件里按 <code>FileAlignment</code>（如 <code>0x200</code>）对齐，映射进内存后按 <code>SectionAlignment</code>（如 <code>0x1000</code>）对齐</strong>。所以同一个节区，在文件里的偏移和在内存里的 RVA 通常不相等——这正是上一章「文件偏移 ≠ RVA」的根源。</p><p data-src-line="24" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">映射完成后，内存里的镜像就是「模块」（module），其起始地址就是模块基址（module base）。如果因为地址冲突或 ASLR，实际基址偏离了 <code>ImageBase</code>，加载器就按重定位表修正代码里的绝对地址。</p><h2 id="_3-解析导入表-填充-iat" tabindex="-1" data-src-line="26" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">3. 解析导入表：填充 IAT <a class="header-anchor" href="#_3-解析导入表-填充-iat" aria-label="Permalink to &quot;3. 解析导入表：填充 IAT&quot;">​</a></h2><p data-src-line="28" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">映射完自己的节区后，加载器看导入表，逐项处理：</p><ol data-src-line="30" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><li data-src-line="30" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">对每个被依赖的 DLL，把它也加载进进程地址空间（如果还没加载）。</li><li data-src-line="31" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">对每个导入函数，找到它在对应 DLL 里的真实地址。</li><li data-src-line="32" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">把这些真实地址填入本模块的 <strong>IAT（导入地址表）</strong>。</li></ol><p data-src-line="34" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">这一步完成之前，程序的代码还不能调用导入函数（因为 IAT 里还没有有效地址）。填完之后，代码里 <code>call [IAT 中的地址]</code> 才能正确跳到系统函数。</p><p data-src-line="36" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">这也是为什么静态分析时，导入函数的地址显示成「符号」；而动态分析时，IAT 里已经是真实地址。</p><h2 id="_4-处理重定位-修正绝对地址" tabindex="-1" data-src-line="38" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">4. 处理重定位：修正绝对地址 <a class="header-anchor" href="#_4-处理重定位-修正绝对地址" aria-label="Permalink to &quot;4. 处理重定位：修正绝对地址&quot;">​</a></h2><p data-src-line="40" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">如果模块被加载到非首选基址，加载器遍历重定位表，把代码里所有写死的绝对地址统一加上「实际基址 - ImageBase」的偏移量。这样代码里引用全局变量、字符串、函数的绝对地址才指向正确位置。</p><p data-src-line="42" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">ASLR 开启时，这一步每次都发生，所以每次运行的绝对地址都不同。</p><h2 id="_5-执行-tls-回调与跳转入口点" tabindex="-1" data-src-line="44" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">5. 执行 TLS 回调与跳转入口点 <a class="header-anchor" href="#_5-执行-tls-回调与跳转入口点" aria-label="Permalink to &quot;5. 执行 TLS 回调与跳转入口点&quot;">​</a></h2><p data-src-line="46" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">在跳转到真正的入口点之前，加载器会先执行 <strong>TLS 回调函数</strong>（如果存在）。这就是上一章说的「程序可以在 <code>main</code> 之前执行代码」的机制。</p><p data-src-line="48" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">最后，加载器跳转到 <code>AddressOfEntryPoint</code> 指向的入口点。对 C/C++ 程序，这里通常是 CRT 初始化代码，再由它调用 <code>main</code>。从这里开始，程序进入「用户代码」的执行阶段。</p><h2 id="_6-这条链路对逆向的意义" tabindex="-1" data-src-line="50" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">6. 这条链路对逆向的意义 <a class="header-anchor" href="#_6-这条链路对逆向的意义" aria-label="Permalink to &quot;6. 这条链路对逆向的意义&quot;">​</a></h2><p data-src-line="52" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">理解加载过程，能解释逆向中几个常见现象：</p><table tabindex="0"><thead data-src-line="54" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><tr data-src-line="54" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><th style="text-align:left;">现象</th><th style="text-align:left;">解释</th></tr></thead><tbody data-src-line="56" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><tr data-src-line="56" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><td style="text-align:left;">文件里和内存里的地址对不上</td><td style="text-align:left;">节区按不同粒度对齐，文件偏移 ≠ RVA</td></tr><tr data-src-line="57" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><td style="text-align:left;">导入函数地址在静态和动态里不同</td><td style="text-align:left;">静态是符号，加载时 IAT 才被填成真实地址</td></tr><tr data-src-line="58" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><td style="text-align:left;">每次运行地址都变</td><td style="text-align:left;">ASLR + 重定位修正</td></tr><tr data-src-line="59" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><td style="text-align:left;">断点还没到入口点就有代码执行</td><td style="text-align:left;">TLS 回调在入口点之前运行</td></tr></tbody></table><p data-src-line="61" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">这些现象背后的机制，正是理解后续动态调试、加壳脱壳的基础。</p><hr><blockquote data-src-line="65" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md"><p data-src-line="65" data-src-file="reverse-engineering/04-pe-format/chapter-04-pe-loading.md">本章把 PE 从文件到进程的链路串了起来：映射节区、解析导入、处理重定位、执行 TLS 回调、跳入口点。到这一章为止，PE 文件格式的骨架已经完整。下一阶段进入更上层的分析——<a href="./../05-static-analysis/chapter-01-basics.html">静态分析</a>。</p></blockquote>`,27)])])}const m=a(i,[["render",d]]);export{f as __pageData,m as default};
